import {researchCatalog,researchSources} from './research-catalog.mjs';
import {runComparison,parseStudyCSV} from './comparison-engine.mjs';
import {clock} from './engine.mjs';
let report=null,loadError='',selectedModel='',selectedFamily='fvg',filter='all',sort='hit',tradeIndex=0,inputs=null,verify='',busy=false,redraw=()=>{},toast=()=>{};
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),pct=n=>n===null?'—':n.toFixed(1)+'%',dt=t=>clock(t).day+' '+clock(t).hm+' ET',tm=t=>clock(t).hm+' ET';
const hash=async txt=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(txt)))).map(v=>v.toString(16).padStart(2,'0')).join('');
function ranks(){const rows=report.baseline.results.filter(r=>r.id!=='dom'&&r.id!=='pairs');return rows.sort((a,b)=>sort==='net'?b.stats.net-a.stats.net:(b.stats.hitRate??-1)-(a.stats.hitRate??-1));}
const current=()=>report?.baseline.results.find(r=>r.id===selectedModel);
export async function loadStrategyResearch(render,notify){redraw=render;toast=notify;try{const r=await fetch('study/comparison.json',{cache:'no-store'});if(!r.ok)throw Error('The strategy study could not be loaded.');report=await r.json();selectedModel=ranks().find(r=>r.stats.trades)?.id||'fvg-a';}catch(err){loadError=err.message;}redraw();}
async function getInputs(){if(inputs)return inputs;const parsed=await Promise.all(report.inputs.map(async file=>{const r=await fetch(file.file,{cache:'no-store'});if(!r.ok)throw Error('Could not load '+file.symbol+' history.');const text=await r.text();if(await hash(text)!==file.sha256)throw Error(file.symbol+' checksum mismatch.');return parseStudyCSV(text);}));inputs={nq:parsed[0],es:parsed[1]};return inputs;}
function metric(k,v,sub){return `<div class="metric"><div class="metric-top">${k}</div><div class="metric-value">${v}</div><div class="metric-sub">${sub}</div></div>`;}
function hitPlot(){const rows=ranks().filter(r=>r.stats.trades),w=880,h=45+rows.length*37;return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Observed net win rates with broad descriptive 95 percent Wilson intervals"><path d="M220 22H840" stroke="#dce4d2"/>${[0,25,50,75,100].map(x=>`<text x="${220+x*6.2}" y="13" fill="#96a187" font-size="10" text-anchor="middle">${x}%</text><path d="M${220+x*6.2} 20V${h-10}" stroke="#eef1e6"/>`).join('')}${rows.map((r,i)=>{const y=42+i*37,s=r.stats;return `<text x="0" y="${y+4}" fill="#597049" font-size="11">${e(r.name)}</text><path d="M${220+s.hitInterval[0]*6.2} ${y}H${220+s.hitInterval[1]*6.2}" stroke="#bacba3" stroke-width="5" stroke-linecap="round"/><circle cx="${220+s.hitRate*6.2}" cy="${y}" r="5" fill="#3b6245"/><text x="865" y="${y+4}" fill="#7f8f70" font-size="10" text-anchor="end">n=${s.trades}</text>`;}).join('')}</svg>`;}
function leaderboard(){const leader=ranks().filter(r=>r.stats.trades).sort((a,b)=>b.stats.hitRate-a.stats.hitRate)[0],s=leader.stats;return `<section class="panel strategy-study"><div class="panel-heading"><div><div class="eyebrow">SAME DATES / EXPLICIT VARIANTS / NO OPTIMIZATION</div><h2 style="font-size:22px;margin-top:10px">Which variant had the higher hit rate?</h2><p>Eight complete sessions · November 2–11, 2026 · Yahoo MNQ=F and MES=F · simulated execution</p></div><span class="tag amber">EXPLORATORY STUDY</span></div><div class="study-verdict"><div><span class="eyebrow">HIGHEST OBSERVED SINGLE-INSTRUMENT HIT RATE</span><h2>${e(leader.name)} <span>${pct(s.hitRate)}</span></h2><p>${s.wins} net winners / ${s.trades} trades · ${money(s.net)} after modeled costs</p></div><div><h3>No reliable winner established</h3><p>Only ${s.trades} trades for the observed leader. These variants, time window and fills do not establish a general ranking or future performance.</p></div></div><div class="section-header"><h3>Measured results, not advertised ranges</h3><div class="tabs-inline"><button data-study-sort="hit" class="${sort==='hit'?'active':''}">By hit rate</button><button data-study-sort="net" class="${sort==='net'?'active':''}">By net P&L</button></div></div><div class="table-wrap"><table class="study-table"><thead><tr><th>Variant</th><th>Net hit rate</th><th>Wins / trades</th><th>95% interval*</th><th>Net P&L</th><th>Realized W:L</th><th>Closed DD</th><th>Proof</th></tr></thead><tbody>${ranks().map(r=>{const t=r.stats;return `<tr><td>${e(r.name)}<small>${e(r.direction)}</small></td><td>${pct(t.hitRate)}</td><td>${t.wins} / ${t.trades}</td><td>${t.hitInterval?t.hitInterval.map(x=>x.toFixed(1)+'%').join('–'):'—'}</td><td class="${t.net<0?'negative':'positive'}">${money(t.net)}</td><td>${t.realizedPayoff?t.realizedPayoff.toFixed(2)+':1':'—'}</td><td>${money(t.maxDrawdown)}</td><td><button class="link-button" data-study-model="${r.id}">Inspect ↗</button></td></tr>`;}).join('')}</tbody></table></div><p class="study-footnote">Hit rate counts net-positive closed trades; breakevens stay in the denominator. Realized W:L is average net winner ÷ average net loser, not a preset target. No-trade variants have no measured hit rate.</p><div class="hit-plot">${hitPlot()}</div><p class="study-footnote">* Descriptive Wilson intervals assume independent trades. Intraday clustering and comparing several variants weaken inference. Broad, overlapping intervals are not evidence of a clear winner.</p><div class="two-cols"><div class="notice"><strong>Spread model — separate execution assumptions</strong><p>${(()=>{const p=report.baseline.results.find(r=>r.id==='pairs').stats;return `${p.wins}/${p.trades} net winners · ${pct(p.hitRate)} · ${money(p.net)}. Two legs, a close-based stop and next-open exits differ from the single-instrument models.`;})()}</p><button class="link-button" data-study-model="pairs">Inspect spread evidence ↗</button></div><div class="notice"><strong>DOM scalping — not backtested</strong><p>No historical depth/queue dataset was obtained. The 70–85% range you supplied remains unverified; candle data cannot prove it.</p><button class="link-button" data-study-model="dom">View the data requirement ↗</button></div></div></section>`;}
function tradeChart(r){if(!r.trades.length)return '<div class="empty">No executed trades for this variant. Inspect the signal log below.</div>';if(!inputs)return '<div class="empty">Load the historical candles to inspect the chart.<br><button class="button small" id="studyLoadChart" style="margin-top:12px">Load evidence chart ↗</button></div>';const t=r.trades[tradeIndex]||r.trades[0],pair=r.id==='pairs';let bs=inputs.nq.filter(b=>b.t>=t.entryTime-12*60000&&b.t<=t.exitTime+5*60000);const em=new Map(inputs.es.map(b=>[b.t,b]));if(pair)bs=bs.filter(b=>em.has(b.t)).map(b=>({...b,o:2*b.o-5*t.esQty*em.get(b.t).o,c:2*b.c-5*t.esQty*em.get(b.t).c,h:null,l:null}));const w=900,h=280,vals=pair?bs.map(b=>b.c):bs.flatMap(b=>[b.h,b.l]);if(!pair)for(const x of [t.entry,t.stop,t.target])if(Number.isFinite(x))vals.push(x);const hi=Math.max(...vals),lo=Math.min(...vals),span=hi-lo||1,dx=800/Math.max(1,bs.length),y=v=>22+(hi-v)/span*220,x=ts=>15+(ts-bs[0].t)/60000*dx+dx/2;let out=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${pair?'Historical minute-close MNQ/MES dollar spread':'Historical MNQ candles with simulated entry, stop, target and exit'}">`;for(let i=0;i<5;i++){const v=hi-span*i/4;out+=`<path d="M15 ${y(v)}H815" stroke="#e7ecdf"/><text x="830" y="${y(v)+4}" font-size="9" fill="#8a9b7c">${v.toFixed(2)}</text>`;}if(pair)out+=`<polyline points="${bs.map(b=>x(b.t)+','+y(b.c)).join(' ')}" fill="none" stroke="#4d7552" stroke-width="2"/>`;else {for(const b of bs){const color=b.c>=b.o?'#a8bc90':'#355c41',cx=x(b.t);out+=`<path d="M${cx} ${y(b.h)}V${y(b.l)}" stroke="${color}"/><rect x="${cx-dx*.25}" y="${y(Math.max(b.o,b.c))}" width="${Math.max(1,dx*.5)}" height="${Math.max(1,Math.abs(y(b.o)-y(b.c)))}" fill="${color}"/>`;}for(const [label,v,col] of [['ENTRY',t.entry,'#477957'],['STOP',t.stop,'#b57462'],['TARGET',t.target,'#7f965c']])if(Number.isFinite(v))out+=`<path d="M15 ${y(v)}H815" stroke="${col}" stroke-dasharray="5 4"/><text x="20" y="${y(v)-5}" font-size="8" fill="${col}">${label} ${v.toFixed(2)}</text>`;}
for(const [label,ts] of [['ENTRY',t.entryTime],['EXIT',t.exitTime]])out+=`<path d="M${x(ts)} 20V245" stroke="${label==='ENTRY'?'#487746':'#bd9662'}" stroke-dasharray="3 4"/><text x="${Math.min(670,Math.max(20,x(ts)+4))}" y="${label==='ENTRY'?12:26}" font-size="9" fill="#718960">${label} ${tm(ts)}</text>`;for(let i=0;i<bs.length;i+=Math.max(1,Math.floor(bs.length/6)))out+=`<text x="${x(bs[i].t)-10}" y="268" font-size="9" fill="#8c9c7e">${clock(bs[i].t).hm}</text>`;return out+'</svg>'+ (pair?'<p>Minute-close spread line only. This is not an intrabar spread price or a representation of simultaneous executable quotes. Exact modeled leg fills are in the trade log.</p>':'');}
function proof(){const r=current(),s=r.stats,stress=report.stress.find(x=>x.id===r.id)?.stats;return `<section class="panel" id="studyProof"><div class="panel-heading"><div><div class="eyebrow">FOLLOW THE CALCULATION</div><h2 style="margin-top:8px">Inspect the backtest proof</h2></div><a class="button small" href="study/comparison.json" download>↓ Full comparison report</a></div><label>Select the exact variant<select id="studyModel">${report.baseline.results.map(x=>`<option value="${x.id}" ${x.id===selectedModel?'selected':''}>${e(x.name)} · ${x.stats?x.stats.trades+' trades':x.status}</option>`).join('')}</select></label><div class="notice"><strong>Rules tested:</strong> ${e(r.rules)}</div>${!s?`<div class="empty">${e(r.reason)}<br>No hit rate, trades, or performance claim is available.</div>`:`<div class="metrics">${metric('Net hit rate',pct(s.hitRate),s.wins+' wins / '+s.trades+' trades')}${metric('Net result',money(s.net),'Gross '+money(s.gross)+' − fees '+money(s.fees))}${metric('Expectancy / trade',money(s.expectancy),'After modeled costs')}${metric('2× cost stress',money(stress?.net??null),(stress?.trades??0)+' trades; fees + slippage doubled')}</div>${r.trades.length?`<label>Inspect a simulated trade<select id="studyTrade">${r.trades.map((t,i)=>`<option value="${i}" ${i===tradeIndex?'selected':''}>${dt(t.entryTime)} · ${t.side===1?'Long':'Short'}${r.id==='pairs'?' spread':''} · ${money(t.pnl)} · ${e(t.reason)}</option>`).join('')}</select></label>`:''}<div class="evidence-chart">${tradeChart(r)}</div><div class="table-wrap"><table><thead><tr><th>Session</th><th>Signals</th><th>Trades</th><th>Net winners</th><th>Hit rate</th><th>Net P&L</th></tr></thead><tbody>${r.daily.map(d=>`<tr><td>${d.day}</td><td>${d.signals}</td><td>${d.trades}</td><td>${d.wins}</td><td>${pct(d.hitRate)}</td><td class="${d.net<0?'negative':'positive'}">${money(d.net)}</td></tr>`).join('')}</tbody></table></div><details><summary>Every simulated trade — entries, exits and costs (${r.trades.length})</summary><div class="table-wrap"><table><thead><tr><th>Entry / ET</th><th>Side</th><th>Size</th><th>Entry</th><th>Exit</th><th>Stop / target</th><th>Exit / ET</th><th>Fees</th><th>Net P&L</th></tr></thead><tbody>${r.trades.map(t=>`<tr><td>${dt(t.entryTime)}</td><td>${t.side===1?'Long':'Short'}${r.id==='pairs'?' spread':''}</td><td>${r.id==='pairs'?'1 MNQ / '+t.esQty+' MES':t.qty+' MNQ'}</td><td>${r.id==='pairs'?t.entryNQ.toFixed(2)+' / '+t.entryMES.toFixed(2):t.entry.toFixed(2)}</td><td>${r.id==='pairs'?t.exitNQ.toFixed(2)+' / '+t.exitMES.toFixed(2):t.exit.toFixed(2)}</td><td>${r.id==='pairs'?'Close-based basket stop':t.stop.toFixed(2)+' / '+t.target.toFixed(2)}</td><td>${dt(t.exitTime)} · ${e(t.reason)}</td><td>${money(t.fees)}</td><td class="${t.pnl<0?'negative':'positive'}">${money(t.pnl)}</td></tr>`).join('')}</tbody></table></div><button class="button small" id="studyExportTrades" style="margin-top:15px">↓ Download this trade log</button></details><details><summary>Detected and rejected signals (${r.signals.length})</summary><div class="table-wrap"><table><thead><tr><th>Confirmed / ET</th><th>Status</th><th>Reason</th></tr></thead><tbody>${r.signals.map(t=>`<tr><td>${dt(t.confirmedAt)}</td><td>${e(t.status)}</td><td>${e(t.rejection||(t.status==='Simulated'?'Passed written rules':t.status))}</td></tr>`).join('')}</tbody></table></div></details>`}<div class="actions" style="margin-top:20px"><button class="button primary" id="studyRerun" ${busy?'disabled':''}>${busy?'Verifying and rerunning…':'↻ Reproduce all strategy results'}</button></div><p id="studyVerify" role="status">${e(verify)}</p><details><summary>Data, risk settings & limits</summary><p>${e(report.freeze.selection)}</p><p>Shared entry window 09:30–11:30 New York; one open position per model; flatten by 16:00. $100 risk budget, $300 daily entry budget, up to 3 contracts. Assumed round-trip fee $1.24 per contract; 1 adverse tick per entry/market exit. Target-touch fills have no queue model. FVG is short-only; other variants may trade both directions.</p><p>Spread training days: ${report.baseline.hedge.trainingDays.join(', ')}. Fixed hedge: ${report.baseline.hedge.nqQty} MNQ / ${report.baseline.hedge.esQty} MES. A pair’s nominal stop is close-based and can be exceeded.</p><ul>${report.limits.map(t=>`<li>${e(t)}</li>`).join('')}</ul><div class="actions"><a class="button small" href="study/mnq.csv" download>↓ MNQ input</a><a class="button small" href="study/mes.csv" download>↓ MES input</a><a class="button small" href="study/source-manifest.json" download>↓ Source manifest</a><a class="button small" href="study/frozen-config.json" download>↓ Frozen settings</a><a class="button small" href="comparison-engine.mjs" download>↓ Comparison engine</a></div>${report.inputs.map(f=>`<p>${e(f.symbol)} · ${f.rows.toLocaleString()} rows · SHA-256<br><code class="hash">${f.sha256}</code></p>`).join('')}${report.engines.map(f=>`<p>${f.file} · SHA-256<br><code class="hash">${f.sha256}</code></p>`).join('')}</details></section>`;}
function library(){const family=researchCatalog.find(x=>x.id===selectedFamily),visible=researchCatalog.filter(x=>filter==='all'||(filter==='missing'?x.id==='dom':x.id!=='dom'));return `<div class="section-header"><div><div class="eyebrow">THE RESEARCH LIBRARY</div><h2 style="font-size:23px;margin-top:9px">Understand the idea before the score.</h2></div><div class="tabs-inline"><button data-study-filter="all" class="${filter==='all'?'active':''}">All six</button><button data-study-filter="tested" class="${filter==='tested'?'active':''}">Tested</button><button data-study-filter="missing" class="${filter==='missing'?'active':''}">Needs data</button></div></div><div class="strategy-cards">${visible.map((s,i)=>`<button class="strategy-card ${selectedFamily===s.id?'selected':''}" data-family="${s.id}" aria-pressed="${selectedFamily===s.id}"><span class="eyebrow">${e(s.family)}</span><h3>${e(s.name)}</h3><p>${e(s.regime)}</p><span class="tag ${s.id==='dom'?'amber':''}">${s.id==='dom'?'MISSING DEPTH DATA':'WRITTEN VARIANTS TESTED'}</span><span class="card-arrow">↗</span></button>`).join('')}</div><section class="panel research-detail" id="familyDetail"><div class="panel-heading"><h2>${e(family.name)}</h2><span class="tag gray">REVIEWED NOV 12, 2026</span></div><div class="two-cols"><div><h3>How it works</h3><p>${e(family.mechanism)}</p><h3 style="margin-top:22px">What would invalidate the idea?</h3><p>${e(family.failure)}</p><h3 style="margin-top:22px">Data required</h3><p>${e(family.data)}</p></div><div><h3>Exact research approach</h3><p>${e(family.test)}</p><h3 style="margin-top:22px">AI research blueprint</h3><p>${e(family.ai)}</p><div class="notice"><strong>${family.claim?'Your supplied range: '+family.claim:'No universal hit rate established.'}</strong>${family.claim?`<p>Supplied risk:reward range: ${family.rr}. Both are unverified reference claims, not validated MNQ statistics or targets used by this test.</p>`:'<p>Use the measured variant’s sample size and exact exits instead of assigning a generic success rate.</p>'}</div></div></div><div class="section-label">SOURCES & WHAT THEY ACTUALLY ESTABLISH</div>${family.sources.map(id=>{const s=researchSources.find(x=>x.id===id);return `<article class="source-card"><a href="${s.url}" target="_blank" rel="noopener">${e(s.title)} ↗</a><small>${e(s.kind)}</small><p>${e(s.finding)}</p></article>`;}).join('')}<div class="actions" style="margin-top:20px">${family.models.map(id=>`<button class="button small" data-study-model="${id}">Inspect ${e(report.baseline.results.find(x=>x.id===id).name)} ↗</button>`).join('')}</div></section>`;}
function calculator(){return `<section class="panel"><div class="panel-heading"><div><h2>Why hit rate alone can mislead</h2><p>Illustrative arithmetic, separate from the historical results.</p></div></div><div class="settings"><label>Win rate (%)<input id="calcWin" type="number" min="0" max="100" step="1" value="70"></label><label>Average winner (R)<input id="calcReward" type="number" min="0.01" max="20" step="0.1" value="0.5"></label><label>Round-trip cost (R)<input id="calcCost" type="number" min="0" max="5" step="0.01" value="0.05"></label></div><div class="formula" style="margin-top:18px" id="calcResult"></div><p>Assumes every gross loss is 1R, a constant average gross winner, and the same cost per trade. Expected R = p × winner − (1 − p) × 1 − cost. Breakeven hit rate = (1 + cost) ÷ (1 + winner). It is not a forecast.</p></section>`;}
export function strategyResearch(){return `<div class="page-title"><div><div class="eyebrow">STRATEGY RESEARCH / COMPARE THE EVIDENCE</div><h1>Different ideas. One honest test.</h1><p>FVG, breakouts, reversion, opening fades, spreads and order flow—research the mechanism and inspect the measured results.</p></div><div class="actions"><a class="button primary" href="#timeframes">Timeframe study ↗</a><a class="button" href="#backtest">Original FVG backtests ↗</a></div></div>${!report?`<section class="panel"><p>${e(loadError||'Loading the strategy research study…')}</p></section>`:leaderboard()+proof()+library()+calculator()+`<div class="source-line">Research reviewed November 12, 2026. Source links explain mechanisms and prior evidence; the site’s hit rates come only from the downloadable comparison run. No trained AI is used.</div>`}`;}
function calc(){const a=document.getElementById('calcWin');if(!a)return;const p=+a.value/100,w=+document.getElementById('calcReward').value,c=+document.getElementById('calcCost').value,out=document.getElementById('calcResult');if(!Number.isFinite(p+w+c)||p<0||p>1||w<=0||c<0){out.textContent='Enter valid nonnegative costs, a positive winner size, and a win rate from 0 to 100.';return;}const raw=p*w-(1-p)-c,ex=Math.abs(raw)<1e-12?0:raw,be=(1+c)/(1+w)*100;out.textContent=`${(p*100).toFixed(0)}% winners at ${w.toFixed(2)}R → ${ex>=0?'+':''}${ex.toFixed(3)}R per trade after costs. Breakeven hit rate: ${be.toFixed(1)}%${be>100?' (unattainable under these assumptions)':''}.`;}
export function bindStrategyResearch(){document.querySelectorAll('[data-study-sort]').forEach(b=>b.onclick=()=>{sort=b.dataset.studySort;redraw();});document.querySelectorAll('[data-study-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.studyFilter;if(filter==='missing')selectedFamily='dom';else if(filter==='tested'&&selectedFamily==='dom')selectedFamily='fvg';redraw();});document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{selectedFamily=b.dataset.family;redraw();document.getElementById('familyDetail')?.scrollIntoView({behavior:'smooth',block:'start'});});const choose=id=>{selectedModel=id;tradeIndex=0;redraw();document.getElementById('studyProof')?.scrollIntoView({behavior:'smooth',block:'start'});};document.querySelectorAll('[data-study-model]').forEach(b=>b.onclick=()=>choose(b.dataset.studyModel));document.getElementById('studyModel')?.addEventListener('change',e=>choose(e.target.value));document.getElementById('studyTrade')?.addEventListener('change',e=>{tradeIndex=+e.target.value;redraw();});document.getElementById('studyLoadChart')?.addEventListener('click',async()=>{try{await getInputs();redraw();}catch(err){toast(err.message);}});document.getElementById('studyRerun')?.addEventListener('click',async()=>{busy=true;verify='Checking source inputs and engine versions…';redraw();try{for(const file of report.engines){const r=await fetch(file.file,{cache:'no-store'});if(!r.ok||await hash(await r.text())!==file.sha256)throw Error('Engine checksum mismatch: '+file.file);}const data=await getInputs();verify='Replaying all written rules on the saved sessions…';redraw();await new Promise(r=>setTimeout(r,0));const actual=runComparison(data.nq,data.es,report.baseline.config);if(JSON.stringify(actual)!==JSON.stringify(report.baseline))throw Error('Computed results differ from the saved report.');const stress=runComparison(data.nq,data.es,{...report.baseline.config,commission:report.baseline.config.commission*2,slipTicks:report.baseline.config.slipTicks*2});if(JSON.stringify(stress.results.map(r=>({id:r.id,stats:r.stats})))!==JSON.stringify(report.stress))throw Error('Cost-stress results differ from the saved report.');verify='✓ Reproduced exactly: both data hashes, both engine hashes, all variants, trades, signals and daily metrics match. Doubled-cost results also match.';toast('All strategy results reproduced exactly');}catch(err){verify='Verification failed: '+err.message;}busy=false;redraw();});document.getElementById('studyExportTrades')?.addEventListener('click',()=>{const r=current(),u=URL.createObjectURL(new Blob([JSON.stringify({model:r.id,rules:r.rules,stats:r.stats,trades:r.trades},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=r.id+'-trades.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);});for(const id of ['calcWin','calcReward','calcCost'])document.getElementById(id)?.addEventListener('input',calc);calc();}
